/* =========================================
   AETHERIA OMNI-VIEW - GLOBAL STYLES
   ========================================= */

:root {
    /* Palette: Deep Void & Arcane Gold */
    --bg-void: #050508;
    --bg-panel: rgba(20, 24, 35, 0.65);
    --bg-panel-hover: rgba(30, 36, 50, 0.8);
    --border-color: rgba(100, 110, 130, 0.3);
    --border-highlight: rgba(150, 160, 180, 0.5);

    /* Accents */
    --accent-gold: #d4af37;
    --accent-glow: rgba(212, 175, 55, 0.4);
    --accent-crimson: #e74c3c;
    --accent-teal: #1abc9c;
    --accent-purple: #9b59b6;
    --accent-blue: #3498db;

    /* Text */
    --text-main: #e0e6ed;
    --text-muted: #7f8c8d;
    --text-dim: #4a5568;

    /* Spacing & Layout */
    --gap: 8px;
    --radius: 4px;
    --font-display: 'Cinzel', serif;
    --font-data: 'JetBrains Mono', monospace;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-void);
    color: var(--text-main);
    font-family: var(--font-data);
    font-size: 12px;
    line-height: 1.4;
    overflow: hidden; /* Dashboard fits screen */
    height: 100vh;
    width: 100vw;
    background-image: 
        radial-gradient(circle at 10% 20%, rgba(20, 30, 50, 0.4) 0%, transparent 40%),
        radial-gradient(circle at 90% 80%, rgba(50, 20, 50, 0.3) 0%, transparent 40%);
}

/* Ambient Effects */
.noise-overlay {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: url('data:image/svg+xml;utf8,%3Csvg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg"%3E%3Cfilter id="noiseFilter"%3E%3CfeTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves="3" stitchTiles="stitch"/%3E%3C/filter%3E%3Crect width="100%25" height="100%25" filter="url(%23noiseFilter)" opacity="0.04"/%3E%3C/svg%3E');
    pointer-events: none;
    z-index: 999;
}

.vignette {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: radial-gradient(circle, transparent 60%, rgba(0,0,0,0.8) 100%);
    pointer-events: none;
    z-index: 998;
}

/* =========================================
   LAYOUT GRID
   ========================================= */

.dashboard-grid {
    display: grid;
    grid-template-columns: 240px 1fr 320px; /* Sidebar | Main | Right Panel */
    grid-template-rows: 60px 1fr 1fr 200px; /* Header | Map | Feed | Footer */
    grid-template-areas:
        "header header header"
        "sidebar map feed"
        "sidebar economy guild"
        "sidebar footer footer";
    gap: var(--gap);
    padding: var(--gap);
    height: 100vh;
}

/* =========================================
   PANEL STYLES (Base)
   ========================================= */

.panel {
    background: var(--bg-panel);
    border: 1px solid var(--border-color);
    border-radius: var(--radius);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    box-shadow: 0 4px 20px rgba(0,0,0,0.5);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    position: relative;
    transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.panel:hover {
    border-color: var(--border-highlight);
    box-shadow: 0 6px 25px rgba(0,0,0,0.6);
}

.panel-header {
    padding: 10px 15px;
    background: rgba(0,0,0,0.3);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-display);
    font-weight: 700;
    letter-spacing: 1px;
    font-size: 14px;
    color: var(--accent-gold);
    text-shadow: 0 0 5px var(--accent-glow);
}

.live-indicator {
    font-family: var(--font-data);
    font-size: 10px;
    color: var(--accent-crimson);
    animation: pulse 2s infinite;
}

/* =========================================
   SPECIFIC PANELS
   ========================================= */

/* 1. Header Panel */
.header-panel {
    grid-area: header;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    padding: 0 20px;
    background: linear-gradient(90deg, rgba(20,24,35,0.9) 0%, rgba(20,24,35,0.6) 100%);
}

.brand {
    display: flex;
    flex-direction: column;
}

.logo {
    font-family: var(--font-display);
    font-size: 24px;
    font-weight: 900;
    color: #fff;
    letter-spacing: 2px;
    text-transform: uppercase;
}

.logo .accent {
    color: var(--accent-gold);
    font-size: 18px;
}

.server-status {
    font-size: 10px;
    color: var(--text-muted);
    margin-top: 4px;
    font-family: var(--font-data);
}

.status-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background-color: var(--accent-teal);
    box-shadow: 0 0 8px var(--accent-teal);
    margin-right: 6px;
}

.global-metrics {
    display: flex;
    gap: 30px;
}

.metric {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
}

.metric .label {
    font-size: 9px;
    color: var(--text-muted);
    text-transform: uppercase;
    margin-bottom: 2px;
}

.metric .value {
    font-size: 14px;
    font-weight: 700;
    color: #fff;
}

.text-crimson { color: var(--accent-crimson); }
.text-green { color: var(--accent-teal); }

.bar-container {
    width: 80px;
    height: 4px;
    background: rgba(255,255,255,0.1);
    border-radius: 2px;
    margin: 4px 0;
    overflow: hidden;
}

.bar {
    height: 100%;
    background: var(--accent-teal);
    box-shadow: 0 0 10px var(--accent-teal);
}

/* 2. Sidebar */
.sidebar-panel {
    grid-area: sidebar;
    padding: 15px;
}

.nav-group {
    margin-bottom: 25px;
}

.nav-title {
    font-size: 10px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 10px;
    border-bottom: 1px solid var(--border-color);
    padding-bottom: 4px;
}

.nav-list {
    list-style: none;
}

.nav-list li {
    padding: 8px 10px;
    cursor: pointer;
    color: var(--text-main);
    font-size: 12px;
    border-radius: 4px;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    gap: 10px;
}

.nav-list li:hover {
    background: rgba(255,255,255,0.05);
    color: var(--accent-gold);
}

.nav-list li.active {
    background: rgba(212, 175, 55, 0.15);
    color: var(--accent-gold);
    border-left: 3px solid var(--accent-gold);
}

.user-profile {
    margin-top: auto;
    display: flex;
    align-items: center;
    gap: 12px;
    padding-top: 15px;
    border-top: 1px solid var(--border-color);
}

.avatar {
    width: 40px;
    height: 40px;
    background: var(--accent-gold);
    color: #000;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    box-shadow: 0 0 15px var(--accent-glow);
}

.user-info .user-name {
    font-weight: 700;
    color: #fff;
}
.user-info .user-role {
    font-size: 10px;
    color: var(--text-muted);
}

/* 3. Map Panel */
.map-panel {
    grid-area: map;
    position: relative;
}

.map-grid {
    flex: 1;
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    grid-template-rows: repeat(5, 1fr);
    gap: 2px;
    padding: 10px;
    background: rgba(0,0,0,0.2);
}

.map-cell {
    background: rgba(255,255,255,0.03);
    border: 1px solid rgba(255,255,255,0.05);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 9px;
    color: var(--text-dim);
    position: relative;
    transition: all 0.3s;
    cursor: crosshair;
}

.map-cell:hover {
    background: rgba(255,255,255,0.1);
    color: #fff;
    z-index: 10;
    border-color: var(--accent-gold);
}

/* Dynamic coloring for map cells (simulated) */
.map-cell[data-region="North"] { background: rgba(52, 152, 219, 0.1); }
.map-cell[data-region="Center"] { background: rgba(241, 196, 15, 0.1); border: 1px solid var(--accent-gold); }
.map-cell[data-region="East"] { background: rgba(230, 126, 34, 0.1); }
.map-cell[data-region="West"] { background: rgba(52, 73, 94, 0.1); }
.map-cell[data-region="South"] { background: rgba(39, 174, 96, 0.1); }

.map-legend {
    display: flex;
    gap: 15px;
    padding: 8px 15px;
    background: rgba(0,0,0,0.4);
    font-size: 10px;
    border-top: 1px solid var(--border-color);
}

.legend-item { display: flex; align-items: center; gap: 5px; }
.dot { width: 8px; height: 8px; border-radius: 2px; }
.dot.royal { background: var(--accent-gold); }
.dot.rebel { background: var(--accent-crimson); }
.dot.neutral { background: var(--text-muted); }
.dot.danger { background: #8e44ad; }

/* 4. Feed Panel */
.feed-panel {
    grid-area: feed;
}

.feed-container {
    flex: 1;
    overflow-y: auto;
    padding: 10px;
}

/* Custom Scrollbar */
.feed-container::-webkit-scrollbar { width: 4px; }
.feed-container::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }
.feed-container::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 2px; }

.feed-item {
    display: flex;
    gap: 10px;
    padding: 6px 0;
    border-bottom: 1px solid rgba(255,255,255,0.03);
    font-size: 11px;
    animation: slideIn 0.3s ease-out;
}

.feed-item .time {
    color: var(--text-muted);
    font-family: var(--font-data);
    min-width: 55px;
}

.tag {
    padding: 1px 4px;
    border-radius: 2px;
    font-weight: 700;
    font-size: 9px;
    min-width: 40px;
    text-align: center;
}

.tag.epic { background: rgba(155, 89, 182, 0.2); color: var(--accent-purple); border: 1px solid var(--accent-purple); }
.tag.rare { background: rgba(52, 152, 219, 0.2); color: var(--accent-blue); border: 1px solid var(--accent-blue); }
.tag.common { background: rgba(127, 140, 141, 0.2); color: var(--text-muted); border: 1px solid var(--text-muted); }

.feed-item .msg { color: var(--text-main); }
.feed-item strong { color: var(--accent-gold); }

/* 5. Economy Panel */
.economy-panel {
    grid-area: economy;
}

.ticker-wrap {
    overflow: hidden;
    background: rgba(0,0,0,0.3);
    padding: 8px 0;
    white-space: nowrap;
    border-bottom: 1px solid var(--border-color);
}

.ticker {
    display: inline-block;
    animation: ticker 30s linear infinite;
}

.ticker-item {
    display: inline-block;
    padding: 0 20px;
    font-size: 11px;
    color: var(--text-main);
}

.up { color: var(--accent-teal); }
.down { color: var(--accent-crimson); }
.flat { color: var(--text-muted); }

.economy-stats {
    display: flex;
    gap: 10px;
    padding: 10px;
}

.stat-box {
    flex: 1;
    background: rgba(255,255,255,0.03);
    padding: 8px;
    border-radius: 4px;
    text-align: center;
}

.stat-box .label { font-size: 9px; color: var(--text-muted); display: block; margin-bottom: 4px; }
.stat-box .val { font-size: 14px; font-weight: 700; color: #fff; }

